export function getAllCustomizationItems(): CustomizationItem[] {
  return CUSTOMIZATION_GROUPS.flatMap((g) => g.subcategories.flatMap((s) => s.items));
}

export function getCustomizationGroup(groupSlug: string): CustomizationGroup | undefined {
  return CUSTOMIZATION_GROUPS.find((g) => g.slug === groupSlug);
}

export function getGroupItems(group: CustomizationGroup): CustomizationItem[] {
  return group.subcategories.flatMap((s) => s.items);
}

export function getCustomizationSubcategory(
  groupSlug: string,
  subSlug: string,
): { group: CustomizationGroup; sub: CustomizationSubcategory } | undefined {
  const group = getCustomizationGroup(groupSlug);
  if (!group) return undefined;
  const sub = group.subcategories.find((s) => s.slug === subSlug);
  if (!sub) return undefined;
  return { group, sub };
}

export function customizationCardSrc(item: CustomizationItem): string {
  return `/media/customization/${item.group}/${item.sub}/${item.file.replace(/\.webp$/i, '-900.webp')}`;
}

export function customizationOriginalSrc(item: CustomizationItem): string {
  return `/media/customization/${item.group}/${item.sub}/${item.file}`;
}
